INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_IDENTIFY.M_TABLE_ORDER_CHANGED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_IDENTIFY', 'Writes the table as a matrix with the rows and columns in a different order from the table.', '{"question":"Write the table (learners as rows, subjects as columns) as a matrix.","wrong_answer":"subjects as rows","correct_answer":"learners as rows, in the table''s order"}'::jsonb, 'Copies the numbers in any order.', 'The answer subjects as rows as a wrong option, with a reason that names the idea.', 'Keep the table''s layout: row 1 of the table is row 1 of the matrix.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
