INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_IDENTIFY.M_ROW_AS_COLUMN', 'MATH.G9.ALGEBR.MATRICES.MATRIX_IDENTIFY', 'Says a row stands for what a column stands for.', '{"question":"Rows are learners, columns are subjects. What does row 2 show?","wrong_answer":"All marks in subject 2","correct_answer":"All marks of learner 2"}'::jsonb, 'Mixes up across and down.', 'The answer All marks in subject 2 as a wrong option, with a reason that names the idea.', 'Rows go across; a row holds one learner''s marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER.M_ORDER_COLUMNS_FIRST', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER', 'Gives the order as columns by rows.', '{"question":"Order of a matrix with 2 rows and 3 columns?","wrong_answer":"3 x 2","correct_answer":"2 x 3"}'::jsonb, 'Reads across first, like the columns.', 'The answer 3 x 2 as a wrong option, with a reason that names the idea.', 'Rows first, then columns: 2 x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER.M_ORDER_AS_COUNT', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER', 'Gives the number of elements as the order.', '{"question":"Order of a matrix with 2 rows and 3 columns?","wrong_answer":"6","correct_answer":"2 x 3"}'::jsonb, 'Counts the elements.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'The order names rows and columns, not the total.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER.M_ORDERS_SAME_IF_SWAPPED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER', 'Thinks 2 x 3 and 3 x 2 are the same order.', '{"question":"Do a 2 x 3 and a 3 x 2 matrix have the same order?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Thinks of multiplication, where order does not matter.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'Two rows of three is a different shape from three rows of two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER.M_SQUARE_MEANS_FOUR', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ORDER', 'Thinks a square matrix must be 2 x 2.', '{"question":"Is a 3 x 3 matrix a square matrix?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Has only seen 2 x 2 examples.', 'The answer No as a wrong option, with a reason that names the idea.', 'Square means as many rows as columns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION.M_ROW_COLUMN_SWAPPED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION', 'Reads column i, row j instead of row i, column j.', '{"question":"Element in row 1, column 3 of [2 5 7; 4 6 8; 1 3 9]?","wrong_answer":"1","correct_answer":"7"}'::jsonb, 'Counts across first.', 'The answer 1 as a wrong option, with a reason that names the idea.', 'Row first: go down to the row, then across to the column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION.M_WRONG_COLUMN', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION', 'Finds the right row but counts to the wrong column.', '{"question":"Element in row 2, column 2 of [2 5 7; 4 6 8]?","wrong_answer":"8","correct_answer":"6"}'::jsonb, 'Miscounts across.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Put a finger on column 1 and count across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION.M_WRONG_ROW', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION', 'Finds the right column but the wrong row.', '{"question":"Element in row 2, column 3 of [2 5 7; 4 6 8]?","wrong_answer":"7","correct_answer":"8"}'::jsonb, 'Miscounts down.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Count rows from the top: row 1, row 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION.M_COUNT_FROM_ZERO', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ELEMENT_POSITION', 'Counts the first row or column as 0.', '{"question":"Element in row 1, column 1 of [2 5; 4 6]?","wrong_answer":"6","correct_answer":"2"}'::jsonb, 'Counts from 0, as on a number line.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Row 1 is the first row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY.M_ELEMENT_COUNT_ENOUGH', 'MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY', 'Thinks two matrices can be added if they have the same number of elements.', '{"question":"Can a 2 x 3 and a 3 x 2 matrix be added?","wrong_answer":"Yes, both have 6 elements","correct_answer":"No"}'::jsonb, 'Counts elements instead of comparing shapes.', 'The answer Yes, both have 6 elements as a wrong option, with a reason that names the idea.', 'Every element needs a partner in the same position: same rows and same columns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY.M_MULTIPLY_RULE_FOR_ADD', 'MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY', 'Uses the rule for multiplying (columns of A = rows of B) for adding.', '{"question":"A is 2 x 3, B is 3 x 2. Can they be added?","wrong_answer":"Yes, 3 columns and 3 rows","correct_answer":"No"}'::jsonb, 'Has heard the multiplying rule.', 'The answer Yes, 3 columns and 3 rows as a wrong option, with a reason that names the idea.', 'For adding, the orders must be the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY.M_ONLY_SQUARE_ADD', 'MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY', 'Thinks only square matrices can be added.', '{"question":"Can two 2 x 3 matrices be added?","wrong_answer":"No, they are not square","correct_answer":"Yes"}'::jsonb, 'Over-generalises from square examples.', 'The answer No, they are not square as a wrong option, with a reason that names the idea.', 'Any two matrices of the same order can be added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY.M_ROWS_ONLY_COMPARED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY', 'Checks only the number of rows (or only columns).', '{"question":"Can a 2 x 3 and a 2 x 2 matrix be added?","wrong_answer":"Yes, both have 2 rows","correct_answer":"No"}'::jsonb, 'Stops after one check.', 'The answer Yes, both have 2 rows as a wrong option, with a reason that names the idea.', 'Both the rows and the columns must match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY.M_SIGNS_DECIDE', 'MATH.G9.ALGEBR.MATRICES.MATRIX_COMPATIBILITY', 'Thinks negative elements stop matrices from being added.', '{"question":"Can [1 -2] and [3 4] be added?","wrong_answer":"No, one has a negative","correct_answer":"Yes"}'::jsonb, 'Thinks of the elements, not the shape.', 'The answer No, one has a negative as a wrong option, with a reason that names the idea.', 'The signs of the elements do not matter; the orders do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT.M_SUBTRACT_ORDER_SWAPPED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT', 'Subtracts the first matrix''s element from the second''s.', '{"question":"[5 2] - [3 6]","wrong_answer":"[-2 4]","correct_answer":"[2 -4]"}'::jsonb, 'Takes the smaller from the larger.', 'The answer [-2 4] as a wrong option, with a reason that names the idea.', 'First minus second, element by element: 5 - 3 and 2 - 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT.M_MINUS_NEGATIVE_ELEMENT', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT', 'Subtracts a negative element as if it were positive.', '{"question":"[4] - [-3]","wrong_answer":"[1]","correct_answer":"[7]"}'::jsonb, 'Drops the sign of the element.', 'The answer [1] as a wrong option, with a reason that names the idea.', 'Minus a negative is plus: 4 - (-3) = 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT.M_ELEMENTS_MULTIPLIED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT', 'Multiplies matching elements instead of adding.', '{"question":"[2 3] + [4 1]","wrong_answer":"[8 3]","correct_answer":"[6 4]"}'::jsonb, 'Mixes the operations.', 'The answer [8 3] as a wrong option, with a reason that names the idea.', 'Adding matrices adds matching elements.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT.M_ALL_ELEMENTS_SUMMED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT', 'Adds all the elements into one number.', '{"question":"[2 3] + [4 1]","wrong_answer":"10","correct_answer":"[6 4]"}'::jsonb, 'Thinks the answer is a single total.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'The sum is a matrix of the same order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT.M_POSITIONS_MISMATCHED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_ADD_SUBTRACT', 'Adds elements in different positions.', '{"question":"[1 2; 3 4] + [5 6; 7 8], row 1 column 2?","wrong_answer":"9 (2 + 7)","correct_answer":"8 (2 + 6)"}'::jsonb, 'Pairs elements by reading order across both matrices.', 'The answer 9 (2 + 7) as a wrong option, with a reason that names the idea.', 'Each element pairs with the one in the same row and column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_UNKNOWN_ADDED_NOT_SUBTRACTED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Adds the known element to the answer instead of taking it away.', '{"question":"x + 4 = 9 from a matrix sum. x?","wrong_answer":"13","correct_answer":"5"}'::jsonb, 'Adds the numbers in the same position.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'Undo the addition: x = 9 - 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_ANSWER_ELEMENTS_GIVEN', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Gives the elements of the answer matrix as the unknowns.', '{"question":"[x 3] + [4 1] = [9 4]. x?","wrong_answer":"9","correct_answer":"5"}'::jsonb, 'Reads x from the result.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'x is in the first matrix, before the addition.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_SUM_AS_PRODUCT', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Multiplies the unknowns when their sum is asked.', '{"question":"x = 5, y = 4. x + y?","wrong_answer":"20","correct_answer":"9"}'::jsonb, 'Misreads the question.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'x + y means add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS.M_WRONG_POSITION_MATCHED', 'MATH.G9.ALGEBR.MATRICES.MATRIX_UNKNOWN_ELEMENTS', 'Matches an unknown with an element in another position.', '{"question":"[x 3; 2 y] + [4 1; 5 2] = [9 4; 7 6]. y?","wrong_answer":"5 (7 - 2)","correct_answer":"4 (6 - 2)"}'::jsonb, 'Pairs by order of reading, not by position.', 'The answer 5 (7 - 2) as a wrong option, with a reason that names the idea.', 'y is in row 2, column 2: use row 2, column 2 on each side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_PERCENT_NOT_DIVIDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Multiplies the percentage by the distance and forgets to divide by 100.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"2,700 m","correct_answer":"27 m"}'::jsonb, 'Treats 6% as 6.', 'The answer 2,700 m as a wrong option, with a reason that names the idea.', '6% means 6 for every 100: 450 x 6 / 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_DIVIDE_BY_GRADIENT', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Divides the distance by the gradient instead of multiplying.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"75 m","correct_answer":"27 m"}'::jsonb, 'Picks an operation without a reason.', 'The answer 75 m as a wrong option, with a reason that names the idea.', 'Rise = gradient x run.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_GRADIENT_ADDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Adds the gradient to the distance.', '{"question":"A 6% road, 450 m across. Rise?","wrong_answer":"456 m","correct_answer":"27 m"}'::jsonb, 'Treats the gradient as a distance.', 'The answer 456 m as a wrong option, with a reason that names the idea.', 'The gradient is a rate, not a length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE.M_RISE_ONLY_COMPARED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.GRADIENT_REAL_LIFE', 'Compares slopes by the rise alone, ignoring the run.', '{"question":"Roof A rises 3 m over 4 m; roof B rises 4 m over 8 m. Steeper?","wrong_answer":"B","correct_answer":"A"}'::jsonb, 'Thinks higher means steeper.', 'The answer B as a wrong option, with a reason that names the idea.', 'Steepness is rise / run: 0.75 against 0.5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
