INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS.M_RATE_AS_X_INTERCEPT', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS', 'Gives the rate as the answer.', '{"question":"Depth y = 60 - 4x. When is it empty?","wrong_answer":"4","correct_answer":"15"}'::jsonb, 'Picks a number from the equation.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Set y = 0 and solve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS.M_MULTIPLY_NOT_DIVIDE', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS', 'Multiplies instead of dividing when solving for the intercept.', '{"question":"0 = 60 - 4x. x?","wrong_answer":"240","correct_answer":"15"}'::jsonb, 'Undoes the wrong operation.', 'The answer 240 as a wrong option, with a reason that names the idea.', '4x = 60, so x = 60 / 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS.M_X_ZERO_FOR_X_AXIS', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS', 'Puts x = 0 to find where the line meets the x-axis.', '{"question":"y = 2x + 6 meets the x-axis at?","wrong_answer":"(0, 6)","correct_answer":"(-3, 0)"}'::jsonb, 'Mixes which coordinate is zero on which axis.', 'The answer (0, 6) as a wrong option, with a reason that names the idea.', 'On the x-axis the height y is 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS.M_INTERCEPT_NOT_DIVIDED', 'MATH.G9.ALGEBR.EQUATIONS_OF_A_STRAIGHT_.INTERCEPTS', 'Moves the constant across but does not divide by m.', '{"question":"0 = 2x + 6. x?","wrong_answer":"-6","correct_answer":"-3"}'::jsonb, 'Stops halfway.', 'The answer -6 as a wrong option, with a reason that names the idea.', '2x = -6, so x = -3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_NO_FLIP_NEGATIVE', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Keeps the inequality sign when dividing by a negative number.', '{"question":"-3x < 12","wrong_answer":"x < -4","correct_answer":"x > -4"}'::jsonb, 'Treats an inequality exactly like an equation.', 'The answer x < -4 as a wrong option, with a reason that names the idea.', 'Try x = -5: -3 x -5 = 15, not less than 12. Dividing by a negative reverses the sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_FLIP_EVERY_DIVISION', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Reverses the sign whenever it divides, even by a positive number.', '{"question":"3x < 12","wrong_answer":"x > 4","correct_answer":"x < 4"}'::jsonb, 'Learnt "the sign changes" without the reason.', 'The answer x > 4 as a wrong option, with a reason that names the idea.', 'Only a negative divisor reverses it: 6 < 9 gives 2 < 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_FLIP_FOR_NEGATIVE_RHS', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Reverses the sign because the number on the right is negative.', '{"question":"2x > -6","wrong_answer":"x < -3","correct_answer":"x > -3"}'::jsonb, 'Links any minus sign with reversing.', 'The answer x < -3 as a wrong option, with a reason that names the idea.', 'Look at what you divide by, not at the answer side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_FLIP_FOR_X_POSITION', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Thinks the sign reverses because of which side x is on.', '{"question":"Why does -2x > 8 become x < -4?","wrong_answer":"Because x is on the left","correct_answer":"Because both sides were divided by -2"}'::jsonb, 'Remembers a rule about sides.', 'The answer Because x is on the left as a wrong option, with a reason that names the idea.', 'The negative divisor reverses it; x can be on either side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_CONSTANT_ADDED_NOT_SUBTRACTED', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Adds the constant to the other side instead of taking it away.', '{"question":"7 - 3x > 19: first step?","wrong_answer":"-3x > 26","correct_answer":"-3x > 12"}'::jsonb, 'Moves the term without changing its sign.', 'The answer -3x > 26 as a wrong option, with a reason that names the idea.', 'Take 7 from both sides: 19 - 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN.M_BOUNDARY_INCLUDED_WRONG', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.SOLVE_ONE_UNKNOWN', 'Includes the boundary for < or > (or leaves it out for less than or equal to) when giving whole-number answers.', '{"question":"x < 4: the largest whole number?","wrong_answer":"4","correct_answer":"3"}'::jsonb, 'Reads < as up to and including.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'x < 4 leaves out 4: the largest whole number is 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
