INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.NUMBER_LINE_ONE_UNKNOWN.M_CIRCLE_BY_NUMBER_SIGN', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.NUMBER_LINE_ONE_UNKNOWN', 'Chooses the circle by whether the number is negative or positive.', '{"question":"Show x is at least -3.","wrong_answer":"open circle because -3 is negative","correct_answer":"solid circle"}'::jsonb, 'Thinks the sign of the number decides.', 'The answer open circle because -3 is negative as a wrong option, with a reason that names the idea.', 'The inequality sign decides: "at least" includes -3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.ALGEBR.LINEAR_INEQUALITIES.NUMBER_LINE_ONE_UNKNOWN.M_CIRCLE_ALWAYS_SAME', 'MATH.G9.ALGEBR.LINEAR_INEQUALITIES.NUMBER_LINE_ONE_UNKNOWN', 'Always uses the same circle.', '{"question":"Show x < 5 and x at most 5.","wrong_answer":"the same circle for both","correct_answer":"open for <, solid for at most"}'::jsonb, 'Has not noticed the circle carries meaning.', 'The answer the same circle for both as a wrong option, with a reason that names the idea.', 'The circle shows whether 5 itself is in the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
