INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.MEASUR.MONEY.BUREAU_BUY_SELL.M_RETURN_ADDED', 'MATH.G9.MEASUR.MONEY.BUREAU_BUY_SELL', 'Adds the money from selling back to the cost of the trip.', '{"question":"Bought for 26,400; sold back for 3,840. Net cost?","wrong_answer":"30,240","correct_answer":"22,560"}'::jsonb, 'Adds both amounts.', 'The answer 30,240 as a wrong option, with a reason that names the idea.', 'Money back reduces the cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.MEASUR.MONEY.BUREAU_BUY_SELL.M_ONE_RATE_FOR_BOTH', 'MATH.G9.MEASUR.MONEY.BUREAU_BUY_SELL', 'Uses one rate for both buying and selling back.', '{"question":"Buy 200 dollars at 132, sell back 30 at 128. Net cost?","wrong_answer":"170 x 132","correct_answer":"200 x 132 - 30 x 128"}'::jsonb, 'Thinks the rate is fixed.', 'The answer 170 x 132 as a wrong option, with a reason that names the idea.', 'Buying and selling back use different rates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
