INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.MEASUR.MONEY.CROSS_RATE.M_DIRECT_MULTIPLY_CROSS', 'MATH.G9.MEASUR.MONEY.CROSS_RATE', 'Multiplies the shillings by the Ugandan rate directly.', '{"question":"sh 13,000 to USh (1 dollar = sh 130 = USh 3,700).","wrong_answer":"48,100,000","correct_answer":"370,000"}'::jsonb, 'Skips the dollar step.', 'The answer 48,100,000 as a wrong option, with a reason that names the idea.', 'First shillings to dollars: 13,000 / 130 = 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
