INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PARALLEL_GRADIENTS.M_START_HEIGHT_LEFT_OUT', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PARALLEL_GRADIENTS', 'Gives the change in y as the y-coordinate.', '{"question":"R(2, 4), change in y 9. k?","wrong_answer":"9","correct_answer":"13"}'::jsonb, 'Forgets where R starts.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Add the change to R''s y: 4 + 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
