INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS.M_PERP_RECIPROCAL_ONLY', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS', 'Turns the gradient upside down but keeps its sign.', '{"question":"Perpendicular to gradient 2?","wrong_answer":"1/2","correct_answer":"-1/2"}'::jsonb, 'Remembers half the rule.', 'The answer 1/2 as a wrong option, with a reason that names the idea.', 'Turn it upside down and change the sign: they multiply to -1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS.M_PERP_SIGN_ONLY', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS', 'Changes the sign but does not turn the gradient upside down.', '{"question":"Perpendicular to gradient 2?","wrong_answer":"-2","correct_answer":"-1/2"}'::jsonb, 'Thinks perpendicular means opposite.', 'The answer -2 as a wrong option, with a reason that names the idea.', '2 x -2 = -4, not -1. Use -1/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS.M_PERP_SAME_GRADIENT', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS', 'Gives the same gradient as the first line.', '{"question":"Perpendicular to gradient 2?","wrong_answer":"2","correct_answer":"-1/2"}'::jsonb, 'Mixes up parallel and perpendicular.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'The same gradient gives a parallel line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS.M_PERP_SUM_RULE', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS', 'Thinks perpendicular gradients add to 0 or 1.', '{"question":"Why are y = 2x and y = -2x not perpendicular?","wrong_answer":"They are: the gradients add to 0","correct_answer":"The gradients multiply to -4, not -1"}'::jsonb, 'Uses a sum rule.', 'The answer They are: the gradients add to 0 as a wrong option, with a reason that names the idea.', 'The product of the gradients is -1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS.M_PERP_SAME_C', 'MATH.G9.GEOMET.COORDINATES_AND_GRAPHS.PERPENDICULAR_GRADIENTS', 'Thinks perpendicular lines must cross the y-axis at the same point.', '{"question":"Must perpendicular lines have the same c?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Links the angle with the intercept.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'Where a line crosses the y-axis does not set its angle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
