INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY.M_SIMILAR_MEANS_EQUAL', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY', 'Thinks similar figures must have equal sides.', '{"question":"Can a 2 by 3 rectangle be similar to a 4 by 6 rectangle?","wrong_answer":"No, the sides are different","correct_answer":"Yes"}'::jsonb, 'Mixes up similar and congruent.', 'The answer No, the sides are different as a wrong option, with a reason that names the idea.', 'Similar means the same shape: sides multiplied by one factor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY.M_BIGGER_NEVER_SIMILAR', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY', 'Thinks a larger figure cannot be similar to a smaller one.', '{"question":"Is an enlarged photo similar to the original?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Thinks similar means the same size.', 'The answer No as a wrong option, with a reason that names the idea.', 'An enlargement is always similar to the object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY.M_ADDED_LENGTH_SIMILAR', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY', 'Thinks adding the same length to every side gives a similar figure.', '{"question":"6 by 4 grows to 8 by 6. Similar?","wrong_answer":"Yes, each grew by 2","correct_answer":"No: 8/6 is not 6/4"}'::jsonb, 'Thinks equal change keeps the shape.', 'The answer Yes, each grew by 2 as a wrong option, with a reason that names the idea.', 'Similar needs one multiplier: 6/4 = 1.5 but 8/6 = 1.33.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY.M_ANGLES_ONLY_RECTANGLES', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_IDENTIFY', 'Thinks all rectangles are similar because their angles are equal.', '{"question":"Are a 1 by 5 and a 2 by 3 rectangle similar?","wrong_answer":"Yes, all angles are 90","correct_answer":"No"}'::jsonb, 'Checks angles but not ratios.', 'The answer Yes, all angles are 90 as a wrong option, with a reason that names the idea.', 'For shapes with more than three sides, check the side ratios too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE.M_ADD_NOT_MULTIPLY', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE', 'Adds the difference of one pair of sides to another side.', '{"question":"Sides 4 and 6; the 4 becomes 10. The 6 becomes?","wrong_answer":"12","correct_answer":"15"}'::jsonb, 'Thinks shapes grow by adding.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Find the factor: 10 / 4 = 2.5; 6 x 2.5 = 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE.M_DIVIDE_FOR_LARGER', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE', 'Divides by the scale factor when going to the larger figure.', '{"question":"Scale factor 2.5 from small to large. Small side 6. Large side?","wrong_answer":"2.4","correct_answer":"15"}'::jsonb, 'Picks the wrong operation.', 'The answer 2.4 as a wrong option, with a reason that names the idea.', 'The large figure is bigger: multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE.M_WRONG_PAIR_MATCHED', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE', 'Uses a side that matches a different side.', '{"question":"Small sides 3, 4, 5; large shortest 6. Large middle?","wrong_answer":"6 (matching the shortest)","correct_answer":"8"}'::jsonb, 'Does not match corresponding sides.', 'The answer 6 (matching the shortest) as a wrong option, with a reason that names the idea.', 'Shortest with shortest, middle with middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE.M_SHADOW_AS_HEIGHT', 'MATH.G9.GEOMET.SIMILARITY_AND_ENLARGEME.SIMILAR_MISSING_SIDE', 'Gives the shadow length as the height.', '{"question":"A 2 m pole casts 3 m; a tree casts 12 m. Tree height?","wrong_answer":"12","correct_answer":"8"}'::jsonb, 'Reads the number given for the tree.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Height and shadow are in the same ratio: 2/3 of 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
