INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.GEOMET.TRIGONOMETRY.TRIG_FIND_LENGTH.M_TAN_DIVIDED', 'MATH.G9.GEOMET.TRIGONOMETRY.TRIG_FIND_LENGTH', 'Divides the distance by tan instead of multiplying.', '{"question":"40 m away at 35 degrees; tan 35 = 0.7002. Height above the eye?","wrong_answer":"57.1","correct_answer":"28.0"}'::jsonb, 'Rearranges the wrong way.', 'The answer 57.1 as a wrong option, with a reason that names the idea.', 'tan = height / distance, so height = distance x tan.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
